<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain\Event;

use Override;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAsset;

class ThemeAssetDisableEvent extends ThemeAssetUpdateEvent
{
    public function __construct(
        ThemeAsset $payload,
        ThemeAsset $original
    ) {
        parent::__construct($payload, $original);
    }
    #[Override]
    public function eventType(): string
    {
        return 'theme-asset.disable';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
